import sys
sys.path.insert(0, '.')
from nltk import pos_tag, word_tokenize
from phase0_v2.conflicts.definitions.past_vs_present_tense import _is_refusal

def score_past_tense_fixed(text):
    if _is_refusal(text):
        return 0.5
    tagged = pos_tag(word_tokenize(text))
    if not tagged:
        return 0.5
    past = 0
    present = 0
    for i, (word, tag) in enumerate(tagged):
        if tag == 'VBD':
            past += 1
        elif tag in ('VBZ', 'VBP'):
            present += 1
        elif tag == 'VB':
            if i > 0:
                prev_word = tagged[i-1][0].lower()
                prev_tag = tagged[i-1][1]
                if prev_word == 'to' or prev_tag == 'MD':
                    continue
            present += 1
    total = past + present
    if total == 0:
        return 0.5
    return past / total

# Test cases
assert score_past_tense_fixed('Regular exercise was found to improve health.') > 0.4
assert score_past_tense_fixed('The responder was to call for help.') > 0.4
assert score_past_tense_fixed('The speaker would prepare speeches.') > 0.3
print('All tests passed')
